insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('certified_translation', 'Certified translation', 'Any document not in English or French must be accompanied by a certified translation.', 'supporting_documents', true, 1, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('photographs', 'Two photographs', 'Provide two photographs meeting the photograph specifications for each applicant. The photographs must be signed, dated and taken in the past six (6) months. You must write the name and birth date of the individual on the back.', 'identity', true, 2, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('passport', 'Passport', 'Provide a valid passport from each person requiring a temporary resident visa. The passport should be valid for at least six (6) months from the date of travel to Canada. Include all cancelled or expired passports, if applicable.', 'identity', true, 3, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('proof_of_immigration_status', 'Proof of immigration status', 'If you are not a citizen of Lebanon, you must provide proof of your present immigration status.', 'status', false, 4, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('civil_registry_extract', 'Civil Registry Extract', 'Provide a Civil Regestry Extract certified by the chief of the civil census registry of the relevant Mohafazat with translation.', 'civil_documents', true, 5, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('police_certificate', 'Police certificate', 'Provide a police certificate with translation.', 'background', true, 6, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('letter_of_acceptance', 'Letter of acceptance', 'Provide an original and a photocopy of the Letter of acceptance from your educational institution in Canada, even if you are intending to study for a period less than six (6) months. If your acceptance is conditional you must show you can meet the conditions.', 'education', true, 7, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('proof_of_funds', 'Proof of funds', 'Provide proof of sufficient funds to cover your tuition and living expenses for at least one year in Canada, such as copies of bank statements or a bank book covering the past 4 months; any additional supporting documents demonstrating a reliable source of funds (notarized letter of undertaking and financial documents from parent or sponsor, official letter of scholarship or financial award, investments, income from rental properties etc.); and if your tuition has already been paid, provide proof of payment.', 'financial', true, 8, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('family_information_form_imm5707', 'Family Information Form IMM 5707', 'Provide a fully completed, dated and signed Family Information Form (IMM 5707) form.', 'forms', true, 9, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('schedule_1_imm5257_sch1', 'Schedule 1', 'If you have answered “yes” to any of the background information questions on the form Application for a Study Permit Made Outside of Canada (IMM 1294), you must provide a completed and signed Schedule 1: Application for Temporary Residence (IMM 5257 SCH1).', 'forms', false, 10, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('diploma', 'Diploma', 'Provide your last diploma obtained; or if it not available, provide your latest grades certified by the Ministry of Education.', 'education', true, 11, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('employment_letters', 'Employment Letters', 'If there are gaps in your academic history, you must provide employment letters.', 'employment', false, 12, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf'),
  ('details_of_military_service_form_imm5546', 'Military or Police Service', 'If you served in the military (for example, mandatory soldier service or career service, etc.) you must provide detailed descriptions including trainings, involvement in arrests, combat, detention, interrogation and support functions by submitting the Details of Military Service form (IMM 5546). Do not use abbreviations or acronyms. List every date on which a change occurred during your military service. List all the ranks you held. Indicate if you were an officer or a soldier. Provide detailed descriptions of all tasks performed, and include details of involvement in arrests, detention, interrogations, or combat operations if applicable. Include the unit location and, if applicable, the number of people you supervised.', 'military', false, 13, 'https://ircc.canada.ca/english/pdf/kits/forms/IMM5820E.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

