  ('application_letter', 'Application letter', 'Signed and dated, explaining why you want to come to Ireland. It must include your full name, postal address, contact details and the commitment that you will obey the conditions of your visa in full, not rely on public services (e.g. public hospitals) or become a burden on the State, and leave Ireland before your immigration permission expires.', 'application', true, 5, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('accommodation_in_ireland', 'Accommodation in Ireland (e.g. hotel, etc.)', null, 'travel', true, 6, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('employer_letter_and_payslips', 'Letter from the employer (NOT EMPLOYMENT CONTRACT)', 'Including type of employment (temporary, indefinite, etc.), how long you have been employed there, the dates you will be absent from your employment and the date you will be returning to work in that employment; 3 most recent payslips.', 'employment', false, 7, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('self_employment_evidence', 'Documentary evidence of your business/company', 'If you are self-employed, provide official document from the company registrar, latest income tax return, and up to date bank statements (from the past six months) from your business bank account.', 'employment', false, 8, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('study_letter', 'Study- Letter from your college', 'Including the course you are studying, how many years you have been a student there, how many years or terms you have left at that college and that you will be returning there following your visit to Ireland.', 'education', false, 9, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('property_evidence', 'Property - Evidence of any property you own or rent , Lease agreement or Title deed', null, 'financial', false, 10, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('personal_bank_statement', 'Finances', 'If you are paying for your own visit include an up-to-date 6 months DETAILED bank statement. It must be original and on headed bank paper, include your name and address, show money paid in and out of the account over the last 6 months, and include a written explanation of any large movements of money in or out of your account, if appropriate.', 'financial', false, 11, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('sponsor_letter', 'Letter stating they are financing your trip', 'If you are supported by a spouse, partner or member of your family, they should provide an original, signed and dated letter stating that they are financing your trip.', 'financial', false, 12, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('sponsor_bank_statement', 'Bank statement', 'If you are supported by a spouse, partner or member of your family, they should provide a bank statement to the same criteria as described above.', 'financial', false, 13, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('relationship_evidence', 'Evidence of their relationship to you e.g. marriage certificate', 'If you are supported by a spouse, partner or member of your family.', 'family', false, 14, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('previous_visa_refusal_details', 'Previous Visa Refusal Details', null, 'immigration_history', true, 15, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('certified_passport_copy', 'Certified (notarised, certified by your HR department, etc.) copy of all pages of your passport', 'If you wish to send the documents by courier and prefer not to send your original passport.', 'identity', false, 16, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

