  )
  values ('ng', 'ie', 'work', 'Employment Visa Checklist', 1, date '2026-09-03', 'Department of Foreign Affairs, Ireland', 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf', null, null, null, null, false, null, 'pending', null, null, null, '741da7ebc1f4c44728cf53e6aedb3bc6a3483ce9168abb3285c887f9ba13e970')
  on conflict on constraint corridors_corridor_version_key do nothing
  returning id
