insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'Original Passport', 'Valid for at least 6 months after the intended date of arrival in Ireland following visits. Passport must have sufficient space for a visa to be inserted; at least two empty pages are required. A copy of all stamped or containing visas pages of your passport is required.', 'identity', true, 1, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('previous_passports', 'Previous passports', 'Submit all previous passports. The first page and a copy of all stamped or containing visas pages of your old and new passports are required.', 'travel_history', true, 2, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('permission_in_country_of_application', 'Evidence of your permission to be in that country', 'If you are not a national of the country from where you are applying, you must submit evidence of your permission to be in that country e.g. a residence card. You must also have at least 3 months permission to be in that country after your intended date of departure from Ireland.', 'residence_status', false, 3, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('online_application_form', 'Fully completed and signed online application form', 'If the applicant is a minor, signature(s) of the legal guardian(s) is required.', 'application_form', true, 4, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('photographs', 'Two recent photographs', 'Not older than 6 months, 35x45 in colour, preferably biometric type with white background. Write your full name on the back of the photographs submitted with your application.', 'photos', true, 5, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('application_letter', 'A signed letter of application, including your full contact details, in English', 'Letter should outline your reason for wanting to come to Ireland; give details of any members of your family currently in Ireland, the UK, or any other EU Member State; how long you intend to stay in Ireland; where you intend to stay while in Ireland; and undertake that you will observe the conditions of your visa, will not become a burden on the State, and will leave the State on the expiry of your permission to remain.', 'cover_letter', true, 6, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('permission_to_work', 'Evidence of Permission to Work in Ireland', 'You must supply one of the following: Critical Skills Employment Permit, General Employment Permit, Intra-Company Transfer Employment Permit, Contract for Services Employment Permit, Exchange Agreement Employment permit, Internship Employment Permit, Sports & Cultural Employment Permit, or Department of Justice Atypical Employment Permit.', 'employment_authorisation', true, 7, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('employment_contract', 'Employment Contract', null, 'employment', true, 8, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('employer_letter', 'Letter from employer in Ireland', 'Confirming details of the job you will take up and the salary you will be paid.', 'employment', true, 9, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('accommodation_details', 'Details of your accommodation on arrival in the State', null, 'accommodation', true, 10, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('qualifications_and_work_experience', 'Evidence of qualifications and previous work experience', null, 'employment', true, 11, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('bank_statements', 'Detailed bank statements', 'Covering a period of 6 months immediately prior to the application showing sufficient funds to pay travel costs and sustain the applicant on arrival in Ireland. This should be accompanied by the signature circular of the bank.', 'financial_evidence', true, 12, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('bank_letter_for_fixed_term_savings', 'Letter from your bank confirming that you are allowed to withdraw money during your travel period', 'Required where funds are in a fixed term savings account, because a fixed term savings account cannot be accepted unless such a letter is included.', 'financial_evidence', false, 13, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('travel_health_insurance', 'Valid travel health insurance', 'Covering any costs of repatriation for medical reasons, emergency medical care and/or emergency hospital care or death during your stay in Ireland. This insurance must be valid for the whole of this territory and must be valid minimum 3 monthly.', 'insurance', true, 14, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('migration_history_statement', 'Comprehensive statement of your migration history', 'Including in respect of short term / touristic travel. Include details of migration undertaken with or without the required permissions.', 'travel_history', true, 15, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('adverse_migration_history_documents', 'Details and documentation of adverse migration history', 'Where you have adverse migration history (e.g. refusal of leave to land, a requirement to depart, deportation, a refusal of an immigration or residency application) you must provide details and documentation.', 'travel_history', false, 16, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('previous_visa_refusal_details', 'Details of previous visa refusals', 'If you have been refused a visa for any other country, details of this, preferably the original letter issued to you by the authorities of that country, must be submitted.', 'travel_history', false, 17, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf'),
  ('translations', 'Full translation for documents not in English', 'If you submit a document that is not in English, it must be accompanied by a full translation. Each translated document must contain confirmation from the translator that it is an accurate translation of the original document, the date of the translation, the translator’s full name and signature, and the translator’s contact details.', 'translation', false, 18, 'https://assets.ireland.ie/documents/Employment_Checklist_2025_002.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

