    reject_reason, source_hash
  )
  values ('ng', 'ie', 'relocation', 'JOIN FAMILY VISA CHECKLIST', 1, date '2026-09-03', 'Department of Foreign Affairs, Ireland', 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf', null, null, null, null, false, null, 'pending', null, null, null, '261ba17e5c4fec48fcd01a85479f64f8c5f1cdd1de08ccb6c902bc77851f69b8')
  on conflict on constraint corridors_corridor_version_key do nothing
  returning id
