insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('policy_document_confirmation', 'Confirmation you have read and understood the ‘Policy Document On Non-EEA Family Reunification’', 'Applicant is asked to confirm they have read and understood the policy document.', 'formality', true, 1, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('passport', 'Original Passport', 'Valid for at least 6 months after the intended date of arrival in Ireland. Must have at least two empty pages for the visa. A copy of all stamped or visa-containing pages of the passport is required.', 'identity', true, 2, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('previous_passports', 'All previous passports', 'Submit all previous passports. The first page and a copy of all stamped or visa-containing pages of old and new passports are required.', 'identity', true, 3, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('residence_permission_in_country_of_application', 'Evidence of permission to be in the country from where you are applying', 'Required if you are not a national of the country from where you are applying, e.g. a residence card. You must also have at least 3 months permission to be in that country after your intended date of departure from Ireland.', 'residence_status', false, 4, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('online_application_form', 'Fully completed and signed online application form', 'If the applicant is a minor, signature(s) of the legal guardian(s) is required.', 'application', true, 5, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('photographs', 'Two recent photographs', 'Two recent photographs not older than 6 months, 35x45 in colour, preferably biometric type with white background. Write your full name on the back of the photographs.', 'photo', true, 6, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('application_letter', 'A signed letter of application, including your full contact details, in English', 'Should outline your reason for wanting to come to Ireland, provide details of the family member in Ireland who is sponsoring your application, and give details of any other members of your family currently in Ireland, the UK, or any other EU Member State.', 'application', true, 7, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_status_eligibility', 'Sponsor’s Status / Eligibility to Sponsor', 'For an Irish citizen residing in Ireland: clear and legible copy of passport or other documentary evidence of Irish citizenship. For an Irish citizen residing outside Ireland: clear and legible copy of passport showing evidence of residency in that country. For a non-EEA sponsor: clear and legible copy of all pages of passport; where relevant, copy of certificate of registration; copy of current Employment Permit / Researcher (Scientific) Hosting Agreement or other evidence of eligibility to sponsor.', 'sponsor', true, 8, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('marriage_or_civil_partnership_certificate', 'Marriage certificate or civil partnership certificate', 'For spouse or civil partner cases. Marriages/civil partnerships must be capable of recognition under Irish law for other purposes outside of the immigration system.', 'relationship', false, 9, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('spouse_relationship_history', 'Full account of relationship history', 'If your sponsor (spouse/civil partner) is residing in Ireland and you have not resided together since your marriage/civil partnership, provide a full account of your relationship history, including where and when you met, evidenced by e.g. visas, entry/exit stamps on the passport of your spouse, photographs, correspondence by e-mail, telephone etc.', 'relationship', false, 10, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('child_birth_certificate_or_adoption_order', 'Birth certificate, adoption order', 'For child applicants under 18 years and unmarried.', 'relationship', false, 11, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('child_custody_order', 'Evidence of full custody and access rights to the child i.e. a court order', 'Required in the case of a child from a previous marriage or relationship.', 'legal', false, 12, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('other_parent_affidavit', 'Sworn affidavit by the other parent consenting to the child being removed from their home country', 'Required in the case of a child from a previous marriage or relationship where the other parent has some custody or access rights.', 'legal', false, 13, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('minor_travel_consent', 'Written letter of consent from both parents/legal guardians', 'Required if a child is travelling either alone or with a person other than their parent/legal guardian, e.g. an adult relative or nurse.', 'legal', false, 14, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('de_facto_relationship_evidence', 'Evidence that will support the existence and durability of your relationship', 'For de facto partner cases. Examples given include registration certificate of partnership (if applicable), evidence of common ownership of property, joint tenancy of property, on-going correspondence addressed to both partners at the same address, financial dependence/interdependence, or other relevant documentary evidence.', 'relationship', false, 15, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('de_facto_relationship_history', 'A full account of your relationship history', 'For de facto partner cases. Include where and when you met, evidenced by e.g. visas, entry/exit stamps on the passport of partner, photographs, correspondence by e-mail, telephone etc.', 'relationship', false, 16, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('applicant_bank_statements', 'A detailed statement of your bank accounts', 'Covering a six month period immediately prior to your application.', 'financial', true, 17, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_bank_statements', 'A detailed statement of your sponsor’s bank accounts', 'Covering a six month period immediately prior to your application.', 'financial', true, 18, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_earnings_evidence_ireland_resident', 'Evidence that sponsor meets the minimum level of earnings required', 'For a sponsor resident in Ireland: Employment Detail Summary for the 3 years immediately prior to the date of application; 3 recent consecutive pay slips; or if self-employed, Notices of Assessment of income from self-employment for the three most recent years and evidence of earnings in the period since the most recent tax return was filed.', 'financial', false, 19, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('projected_earnings_evidence', 'Evidence of projected earnings', 'For a person who is eligible to sponsor applications for immediate family reunification, e.g. copy of contract of employment.', 'financial', false, 20, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('sponsor_earnings_evidence_after_12_months', 'Evidence that sponsor meets the minimum level of earning required', 'For a person eligible to sponsor applications for family reunification after 12 months: Employment Detail Summaries for the previous 2 years, or previous 1 year in the case of an Employment Permit holder who has been in Ireland for 1 year only, or if self-employed Notices of Assessment of income from self-employment, as appropriate; and 3 recent consecutive pay slips.', 'financial', false, 21, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('employment_permit_holder_contract', 'Copy of contract of employment', 'In the case of an Employment Permit holder, a copy of their contract of employment of at least 1 year from your proposed date of entry giving their annual salary is also required.', 'financial', false, 22, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('family_registration_certificate', 'Detailed family registration certificate', null, 'civil_status', true, 23, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('dependency_evidence', 'Evidence of dependency', 'If applying on the basis of financial and social dependency on your sponsor, provide documentary evidence to establish that you are actually dependent on your sponsor. Relevant evidence may include amount, frequency and duration of financial support; other income sources; if no other income, why you are unable to work or not eligible for State benefits; living costs; details of other family members in your country of residence; and medical condition where relevant, and relationship with the sponsor including evidence of active and continuous involvement in your life.', 'financial', false, 24, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('travel_health_insurance', 'Valid travel health insurance', 'Covering costs of repatriation for medical reasons, emergency medical care and/or emergency hospital care or death during your stay in Ireland. Must be valid for the whole territory and valid minimum 3 monthly.', 'insurance', true, 25, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('migration_history_statement', 'Comprehensive statement of your migration history', 'Include short term / touristic travel and details of migration undertaken with or without the required permissions. Where you have adverse migration history, provide details and documentation.', 'travel_history', true, 26, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('previous_visa_refusals', 'Details of any previous visa refusals', 'If you have been refused a visa for any other country, details of this, preferably the original letter issued by the authorities of that country, must be submitted.', 'travel_history', false, 27, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('visa_fee_and_vfs_service_fee', 'Visa fee and VFS service fee', null, 'fee', true, 28, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('original_documents', 'All documents accompanying your application must be originals', 'Keep copies of all documents provided. If there are documents you wish to have returned, provide a list of these with the application to the VFS agent and ensure they are placed in a separate folder. Submit a photocopy of all documents that you may need back at the time of collection.', 'submission', true, 29, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf'),
  ('translations', 'Full translation for documents not in English', 'If you submit a document that is not in English, it must be accompanied by a full translation. Each translated document must contain confirmation from the translator that it is an accurate translation of the original document, the date of the translation, the translator’s full name and signature, and the translator’s contact details.', 'translation', false, 30, 'https://assets.ireland.ie/documents/Join_Family_Checklist_2025.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

