from c, (values
  ('passport', 'Original Passport', 'Original passport valid for at least 6 months after the intended date of arrival in Ireland. Passport must have sufficient space for a visa to be inserted; at least two empty pages are required. A copy of all stamped or containing visas pages of your passport is required.', 'identity', true, 1, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('previous_passports', 'previous passports', 'You should submit all previous passports. The first page and a copy of all stamped or containing visas pages of your old and new passports are required.', 'identity', true, 2, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('permission_to_apply_from_country_of_residence', 'evidence of your permission to be in that country e.g. a residence card', 'If you are not a national of the country from where you are applying, you must submit evidence of your permission to be in that country. You must also have at least 3 months permission to be in that country after your intended date of departure from Ireland.', 'residence_status', false, 3, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('online_application_form', 'Fully completed and signed online application form', null, 'application', true, 4, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('photographs', 'Two recent photographs', 'Two recent photographs (not older than 6 months) 35x45 in colour, preferably biometric type with white background. Please write your full name on the back of the photographs you submit along with your application.', 'photos', true, 5, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('letter_of_application', 'A signed letter of application, including your full contact details, in English', 'The letter should outline your reason for wanting to come to Ireland; give details of any other members of your family who are currently in Ireland, the UK, or any other EU Member State; state how long you plan to stay; state that the cost of trip is being borne by yourself or, where that is not the case, details of the third party funding the costs of the trip; provide the name, phone number and e-mail address of the contract organiser in Ireland; provide reasons for obligations to return to your country; and state that you will observe the conditions of your visa, that you will not become a burden on the State and that you will leave the State on the expiry of your permission to remain.', 'cover_letter', true, 6, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
