  ('sgk_registration', 'SGK (social security) registration document and SGK "hizmet dökümü" / payment of premium', 'Required if applicant is employed.', 'employment', false, 10, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
