  ('trade_register_bulletin', 'bulletin of the trade register', 'Required if applicant is self-employed or owner of a private company.', 'business', false, 13, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('company_tax_registration_certificate', 'tax registration certificate of the company', 'Required if applicant is self-employed or owner of a private company.', 'business', false, 14, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('farmer_certificate', 'farmer certificate issued by the Chamber of Agriculture', 'Required if the applicant is a farmer.', 'employment', false, 15, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('proof_of_pension', 'proof of pension', 'Required if the applicant is retired; either bank account or pensioner booklet.', 'financial', false, 16, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('evidence_of_enrolment', 'evidence of enrolment', 'Required if the Conference is in respect the Applicant’s course of studies.', 'study', false, 17, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('university_support_letter', 'a letter from the University / course provider confirming their support of your attendance at the course, and that the conference is linked to your studies', 'Required if the Conference is in respect the Applicant’s course of studies.', 'study', false, 18, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('conference_host_letter', 'Letter from conference host confirming applicant will be attending conference', 'The letter should include details of the nature, dates, place, duration of conference and that the registration fees have been paid. This letter should be on headed paper and clearly state the phone number, business address and email address.', 'invitation', true, 19, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('bank_statements', 'detailed bank statements covering a period of 6 months immediately prior to the application', 'If applicant is responsible for costs of this trip, bank statements should show sufficient funds to pay travel costs and sustain the applicant on arrival in Ireland. This should be accompanied by the signature circular of the bank. The applicant must have immediate access to these funds, and therefore, a fixed term savings account cannot be accepted, unless a letter is included from your bank confirming that you are allowed to withdraw money during your travel period.', 'financial', false, 20, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('sponsorship_letter', 'a sponsorship letter', 'For minors and persons without their own resources, a sponsorship letter shall be submitted stating that a parent/other person shall cover the expenses, with a proof of the social & professional status of the person offering to cover the expenses and a proof that such a person has the resources.', 'financial_support', false, 21, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('hotel_reservation', 'Confirmed hotel reservation', 'Confirmed hotel reservation valid for entire stay. The dates of the hotel reservation should correspond to your flight reservation.', 'accommodation', true, 22, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('uk_trip_information', 'information about entrance to UK, permission to travel to the UK and detailed information of entire trip', 'Required if you are also visiting the UK.', 'travel_itinerary', false, 23, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('travel_health_insurance', 'Valid travel health insurance', 'Valid travel health insurance covering any costs of repatriation for medical reasons, emergency medical care and/or emergency hospital care or death during your stay in Ireland. This insurance must be valid for the whole of this territory and this insurance must be valid minimum 3 monthly.', 'insurance', true, 24, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('migration_history_statement', 'a comprehensive statement of your migration history', 'You should provide a comprehensive statement of your migration history, including in respect of short term / touristic travel. You should include details of migration undertaken with or without the required permissions. Where you have adverse migration history (e.g. refusal of leave to land, a requirement to depart, deportation, a refusal of an immigration or residency application) you must provide details and documentation.', 'travel_history', true, 25, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('previous_visa_refusal_details', 'details of previous visa refusals', 'If you have been refused a visa for any other country, details of this, preferably the original letter issued to you by the authorities of that country, must be submitted.', 'travel_history', false, 26, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('visa_fee_and_vfs_service_fee', 'Visa fee and VFS service fee', null, 'fees', true, 27, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('original_documents', 'All documents accompanying your application must be originals', 'You should keep copies of all the documents that you provide. If there are particular documents that you wish to have returned, please provide a list of these documents with the application to the VFS agent, and ensure they are placed in a separate folder. Please submit a photocopy of all the documents that you may need back at the time of collection.', 'submission', true, 28, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf'),
  ('translations', 'full translation', 'If you submit a document that is not in English, it must be accompanied by a full translation. Each translated document must contain confirmation from the translator that it is an accurate translation of the original document, the date of the translation, the translator’s full name and signature, and the translator’s contact details.', 'translation', false, 29, 'https://assets.ireland.ie/documents/Conference_Checklist_2025.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

