  ('moha_approval_letter', 'Valid MOHA approval letter for international student intake', null, 'institutional', true, 6, 'https://www.imi.gov.my/index.php/en/main-services/pass/student-pass/'),
  ('academic_results_transcripts', 'Academic results and transcripts', 'Source 1 says copies of all academic records, certificates or transcripts of studies previously undertaken are needed.', 'education', true, 7, 'https://www.imi.gov.my/index.php/en/main-services/pass/student-pass/'),
  ('personal_bond_form', 'Personal Bond form (stamped)', 'Source 1 states the Immigration Department requires education institutions in Malaysia to sign a personal bond on behalf of the candidate, and notes the personal bond form can be submitted after arrival in Malaysia for student pass endorsement.', 'financial', true, 8, 'https://www.imi.gov.my/index.php/en/main-services/pass/student-pass/'),
  ('health_insurance_policy', 'Health Insurance Policy recognized in Malaysia with a coverage period of at least 12 months.', null, 'insurance', true, 9, 'https://www.imi.gov.my/index.php/en/main-services/pass/student-pass/'),
  ('authorisation_letter_sarawak', 'Letter of Authorization from the Institution of Higher Learning (Sarawak only)', 'Source 1 says this is to confirm the university''s representative that will be handling the application and documentation of the student.', 'institutional', false, 10, 'https://www.imi.gov.my/index.php/en/main-services/pass/student-pass/'),
  ('cover_letter_sarawak', 'Cover Letter from the Institution of Higher Learning (Sarawak only)', 'Source 1 says this is issued by the institute to Sarawak Immigration, to inform the student''s intention of applying for the student pass.', 'institutional', false, 11, 'https://www.imi.gov.my/index.php/en/main-services/pass/student-pass/'),
  ('pre_val_medical_report_sarawak', 'Pre-VAL Medical Report / Health Report from Country of Origin (Sarawak only)', 'Source 1 says to upload the Pre-VAL Medical Report from the country of residence if screening was done at a non-EMGS registered overseas clinic; if the screening was at a registered clinic, this step can be skipped.', 'medical', false, 12, 'https://www.imi.gov.my/index.php/en/main-services/pass/student-pass/'),
  ('health_declaration_form', 'Health Declaration Form', 'Required to be filled up and submitted; for online applications, a scanned copy must be uploaded.', 'medical', true, 13, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('english_language_certificate', 'English Language Requirement', 'When applying for a Visa Approval Letter (VAL), the applicant must demonstrate an acceptable level of English language proficiency and upload the certificate as part of the application. Accepted tests listed are MUET, IELTS/IELTS Online, TOEFL iBT, TOEFL Essentials (Online), PTE Academic/PTE Academic (Online), Cambridge English B1 Preliminary, B2 First, C1 Advanced, C2 Proficiency, Cambridge English Linguaskill Online, Cambridge English Occupational English Test (OET) (Conventional/Online), and ELS Certified Intensive English Programme Level (CIEP Level).', 'education', true, 14, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('special_pass_or_exit_stamp', 'Special Pass or Exit Stamp', 'Required if applicable.', 'passport', false, 15, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents'),
  ('yellow_fever_vaccination_booklet', 'yellow fever vaccination booklet/card', 'Required only if coming from a country considered to be at a high risk of yellow fever; it must be provided before clearing Immigration at the point of entry.', 'medical', false, 16, 'https://visa.educationmalaysia.gov.my/guidelines/required-documents')
