  ('flight_itinerary', 'FLIGHT ITINERARY (RESERVATION ONLY)', 'Reservation only.', 'travel', true, 5, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('travel_medical_insurance', 'TRAVEL MEDICAL INSURANCE (TMI)', 'One copy of the certificate of TMI issued by a company from the list of approved Indian insurance companies which meet the necessary conditions referred to in Article 25 (1) (2) (a) and Article 25 (1b) of the Act of 12 December 2013 on Foreigners; handwritten certificates will not be accepted; the name of the insured should be written in Latin alphabet; TMI must be valid in the Schengen area and for the entire duration of stay; the TMI''s minimum coverage is 30.000 euro and it must cover costs of any emergency medical treatment and repatriation for medical reasons as well as in case of death repatriation of the deceased.', 'insurance', true, 6, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
