  ('work_permit', 'Original and valid work permit and its copy', null, 'employment', true, 8, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('employing_company_registration', 'Proof of registration of the employing company', 'KRS – National Court Register of Poland.', 'employment', true, 9, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('employment_letter', 'Original employment letter from the applicant''s employer in Poland', 'On the official company paper with stamp and signature, date and clearly mentioning: full address and contact details of the company, the name and position of the countersigning officer, details regarding the employment of the applicant (e.g. position, salary, estimated duration), details regarding additional conditions of employment (e.g. accommodation, transport, living expenses).', 'employment', true, 10, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('international_transfer_letter', 'letter from the current employer confirming the transfer, and approving the leave/absence of the applicant', 'In case of international transfer of the employee.', 'employment', false, 11, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('professional_educational_certificates', 'Professional/educational certificates proving professional skills', 'Copies and originals legalized/attested/apostilled by MEA/MFA.', 'qualification', false, 12, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('work_experience_certificate', 'Work experience certificate', 'Copies and originals.', 'employment', false, 13, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('police_clearance_certificate', 'Police Clearance Certificate', null, 'background', false, 14, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('accommodation_proof', 'ACCOMODATION', 'Document confirming the booking of appropriate accommodation for the intended period of stay in Poland: lease agreement or other type of accommodation proof.', 'accommodation', true, 15, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('additional_documents', 'ADDITIONAL DOCUMENTS', 'Applicants are allowed to submit additional documents that they consider useful to explain/justify the trip.', 'supporting', false, 16, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
  ('residence_proof', 'RESIDENCE PROOF', 'An ID confirming legal residence within the Embassy’s / Consulate’s jurisdiction.', 'residence', true, 17, 'https://www.gov.pl/attachment/d186b975-66c7-4b22-a3ec-b0ff2f9730f0'),
