from c, (values
  ('visa_application_form', 'A completed visa application form filled via the e-konsulat system, printed and signed.', null, 'application', true, 1, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('photo', 'A 3.5 x 4.5 cm colour photo.', 'The photo must be sharp, against white background, printed on quality paper, newer than 6 months, taken straight ahead, clearly showing the eyes and face on both sides from the top of the head to the top of the shoulders, with the face covering 70-80% of the photo. The photo must be taken without any headwear.', 'photo', true, 2, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('passport', 'Passport', 'Issued within the last 10 years, valid for at least three months from the expected return date, with at least two blank pages for visas. If you have a second valid passport, please attach it to your visa application.', 'identity', true, 3, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
