  ('medical_or_health_insurance', 'A document confirming the possession of travel medical insurance or a document confirming the possession of health insurance', 'Travel medical insurance with an insurance amount of no less than EUR 30,000 must be valid for the period of the intended stay in Poland and cover expenses due to the necessity of return travel for medical reasons, urgent medical assistance, emergency hospital treatment or death, with the insurer undertaking to cover healthcare costs directly to the provider on the basis of a bill issued by that entity.', 'insurance', true, 6, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('legal_residence_document', 'A document to confirm legal residence within the consular district of your application.', null, 'residence', true, 7, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('financial_resources', 'Documents confirming the possession of financial resources to cover the costs of return travel and the costs of stay in Poland.', 'The minimum required amount is stated as: if applicant is alone in Poland: 2 500 PLN for a return trip; cost of accommodation on the basis of hotel booking or rental agreement; 776 PLN for every month of stay. If applicant stays in Poland with family members: 2 500 PLN for a return trip; cost of accommodation on the basis of hotel booking or rental agreement; 600 PLN for every month of stay for the applicant and each member of family. Required documents may be selected from the listed options; there is no obligation to present all listed ones.', 'financial', true, 8, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('bank_statement', 'Original bank statement from the last 6 months', 'Containing contact details of the bank employee responsible for confirming documents. Listed as one option for confirming possession of financial resources.', 'financial', false, 9, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('polish_bank_funds_certificate', 'The original certificate of the possession of funds in a bank having its registered office in the territory of the Republic of Poland.', 'Listed as one option for confirming possession of financial resources.', 'financial', false, 10, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('sponsorship_letter', 'The original of the sponsorship letter confirmed by the consul', 'If the applicant does not cover his stay in Poland by himself. The sponsor confirms funds to cover return trip and stay on the basis of the listed financial documents. Only a family member may be a sponsor; the applicant should present documents confirming the relationship.', 'financial', false, 11, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('scholarship_proof', 'A document confirming the granting of a national or foreign scholarship.', 'Listed as one option for confirming possession of financial resources.', 'financial', false, 12, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('accommodation_proof', 'Written proof of accommodation in Poland for the entire period of validity of the visa, along with the amount of the rental.', 'Applicants who intend to live with family or friends, or who are sponsored by Polish / EU citizens in any other way, are required to submit an invitation registered with appropriate Polish authorities (Urząd Wojewódzki).', 'accommodation', true, 13, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('acceptance_letter', 'The original acceptance letter of the unit conducting the studies on admission to studies or on continuation of studies.', null, 'study', true, 14, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('fee_payment_proof', 'Proof of payment of the fees', 'If applicable.', 'study', false, 15, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('recruitment_diplomas', 'Diplomas being the basis for recruitment for studies with superlegalisation.', null, 'education', true, 16, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('additional_education_documents', 'Other additional documents confirming education (eg. English certicicate, course and training diplomas/certificates) with superlegalisation.', 'Documents should be presented in English or Polish.', 'education', true, 17, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('minor_parental_consent', 'Written consent of the child’s/minor’s parent(s) to apply for a visa, confirmed by a notary.', 'Required additionally when applying for a visa for a minor. If there is only one guardian, it should be proved by a birth certificate, a court decision on exclusive parental custody or a death certificate of the other parent.', 'minor', false, 18, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('minor_parents_passports', 'Parents’ passports – originals and copies.', 'Required additionally when applying for a visa for a minor.', 'minor', false, 19, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa'),
  ('minor_birth_certificate', 'Birth certificate – original and copy.', 'Required additionally when applying for a visa for a minor.', 'minor', false, 20, 'https://www.gov.pl/web/nigeria-en/d-type-national-visa')
