  ('financial_means', 'Proof of financial means', 'One of the below: a statement of account from your bank confirming that you have money of your own to support yourself with; or a document issued in your name showing that you have received a scholarship or a similar means of support and describing both the monthly sum and the period during which you will receive the money; or a document showing that you have received a training grant (applies to doctoral students) or a studentship, with details of the amounts and the period concerned.', 'financial', true, 8, 'https://www.swedenabroad.se/en/about-sweden-non-swedish-citizens/nigeria/going-to-sweden/studying-in-sweden/residence-permit-studies---required-documents/'),
  ('bank_statement', 'bank statement', 'For personal bank assets, it must be issued no more than four months before the date on which you want the residence permit to take effect and include account holder(s), bank name, date of issue, balance, and currency. If permission from a central bank or the equivalent is required to take out the money from your country, you must include such a permit.', 'financial', false, 9, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html'),
  ('scholarship_document', 'copy of the scholarship', 'Must state who is the scholarship provider, that you are the recipient, the period for which the scholarship applies and that it is for your studies in Sweden, how much money you will receive, when the money will be paid out, and how much of the scholarship is intended to cover your living expenses. If the copy does not contain all of this information, you must supplement it with, for example, a certificate from the scholarship provider.', 'financial', false, 10, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html'),
  ('sponsorship_letter', 'sponsorship letter', 'Must state who is the sponsor or guarantor, that you are the recipient of the money, how much money you will receive, when the money will be paid out, the period during which you are sponsored, how much of the money will be used for your living expenses, and whether the sponsorship requires some form of performance on your behalf.', 'financial', false, 11, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html'),
  ('employment_certificate', 'certificate of employment', 'Must include your employer''s name, contact details and company registration number, your salary or wages, duration and scope of your employment in hours per week, when the job started, and last day of employment. If you quit the job, this must be stated in the certificate.', 'financial', false, 12, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html'),
  ('student_grant_or_loan_certificate', 'certificate stating student grant or loan from your country of origin', 'Must state who is providing the student grant or loan, that you are the recipient, the period for which the grant or loan applies, when it will be paid out, the monthly amount or total amount for the period of study, and how much is intended for your living expenses.', 'financial', false, 13, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html'),
  ('health_insurance', 'document showing that you have comprehensive health insurance valid in Sweden', 'Required if you will be studying for less than a year. If you are covered by insurance from the university or university college concerned, you must send a certificate showing this.', 'insurance', false, 14, 'https://www.swedenabroad.se/en/about-sweden-non-swedish-citizens/nigeria/going-to-sweden/studying-in-sweden/residence-permit-studies---required-documents/'),
  ('health_insurance_documents', 'Documents showing that you have or have applied for comprehensive health insurance', 'Required if you have been admitted to studies for less than one year and are not listed in Sweden’s population register.', 'insurance', false, 15, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

